package com.exe201.rrms.controller;
import com.exe201.rrms.entity.*;import com.exe201.rrms.repository.*;import com.exe201.rrms.service.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/matching") public class MatchingController {private final AuthService auth;private final MatchingProfileRepository profiles;private final MatchingService match;private final ListingInterestRepository interests;public MatchingController(AuthService a,MatchingProfileRepository p,MatchingService m,ListingInterestRepository i){auth=a;profiles=p;match=m;interests=i;} @GetMapping("/profile") public MatchingProfile profile(HttpServletRequest r){User u=auth.current(r);return profiles.findByUserId(u.getId()).orElseGet(()->{MatchingProfile p=new MatchingProfile();p.setUserId(u.getId());p.setGender(u.getGender());p.setSchoolName(u.getSchoolName());p.setLatitude(u.getHomeLat());p.setLongitude(u.getHomeLng());p.setRadiusKm(u.getMatchingRadiusKm());return p;});} @PutMapping("/profile") public MatchingProfile save(HttpServletRequest r,@RequestBody MatchingProfile d){User u=auth.current(r);MatchingProfile p=profiles.findByUserId(u.getId()).orElseGet(MatchingProfile::new);Long id=p.getId();org.springframework.beans.BeanUtils.copyProperties(d,p,"id","userId");p.setId(id);p.setUserId(u.getId());return profiles.save(p);} @GetMapping("/listing/{listingId}") public List<Map<String,Object>> same(@PathVariable Long listingId,HttpServletRequest r){User u=auth.current(r);ListingInterest i=interests.findByListingIdAndUserId(listingId,u.getId()).orElseThrow(()->new IllegalStateException("Bạn cần bấm Quan tâm phòng trước"));if(!Boolean.TRUE.equals(i.getMatchingEnabled()))throw new IllegalStateException("Hãy bật 'Tìm bạn ở cùng' cho phòng này");return match.sameRoom(u.getId(),listingId);} @GetMapping("/nearby") public List<Map<String,Object>> nearby(@RequestParam(defaultValue="5")int radiusKm,HttpServletRequest r){return match.nearby(auth.current(r).getId(),Math.min(5,Math.max(1,radiusKm)));} }
